strategic-plan.value:
{
  "project": {
    "name": "santiago-allamand-landingpage",
    "path": "/var/home/rixmerz/my_projects/xpteam/clientes-landingpages/santiago-allamand-landingpage/",
    "framework": "Deno Fresh 2.x + Preact + Tailwind CSS 4",
    "language": "es"
  },
  "palette": {
    "dark": "#1a1a2e",
    "dark_surface": "#252540",
    "accent": "#5e67e6",
    "accent_hover": "#4d55d4",
    "accent_lime": "#d0ff71",
    "white": "#ffffff",
    "offwhite": "#f8f8fa",
    "light_gray": "#f0f0f5",
    "text_primary": "#1a1a2e",
    "text_secondary": "#6b6b80",
    "text_muted": "#9999aa",
    "border": "#e0e0e8",
    "red_accent": "#ff5e2b",
    "success": "#0bde66"
  },
  "fonts": {
    "headings": "Antonio (Google Fonts) - condensed, bold, uppercase for impact",
    "body": "Inter (Google Fonts) - clean, modern, all weights",
    "accent": "Satoshi (manual or fallback to Inter 700)"
  },
  "sections": [
    {
      "id": "navbar",
      "component": "Navbar.tsx",
      "content": "Logo SA, links: Inicio, Sobre Mí, Cursos, Podcasts, Contacto. Fixed top, backdrop-blur, dark bg. Mobile hamburger menu.",
      "effects": "Scroll shadow, backdrop-blur on scroll, nav links hover underline animation"
    },
    {
      "id": "hero",
      "component": "Hero.tsx",
      "content": "Large heading SANTIAGO ALLAMAND in Antonio font. Subtitle: Finanzas Personales · Productividad · Estilo de Vida. Intro paragraph about exploring curiosity. CTA button. Profile photo.",
      "effects": "Fade-in-up staggered animation on heading/subtitle/paragraph/CTA. Parallax-lite on background element. Hover scale on CTA."
    },
    {
      "id": "pillars",
      "component": "Pilares.tsx",
      "content": "3 pillars: Finanzas Personales (icon + description), Productividad (icon + desc), Estilo de Vida (icon + desc). Section title: Lo Que Exploro.",
      "effects": "Cards fade-in-up staggered. Hover: card lifts with shadow, accent border appears. Icon color shift on hover."
    },
    {
      "id": "about",
      "component": "SobreMi.tsx",
      "content": "Bio: Abogado, inversionista, profesor universitario, creador de contenido. Stats: 700K+ seguidores, 1.5M+ descargas podcast, 10+ años enseñando. Philosophy paragraph. Photo.",
      "effects": "Stats counter animation on scroll (count up). Photo fade-in from side. Text fade-in-up."
    },
    {
      "id": "courses",
      "component": "Cursos.tsx",
      "content": "Section title: Cursos y Recursos. Cards: Del Desorden al Control ($27 USD), Construye Riqueza con ETFs, Principios de Productividad, Curso Gratis Deudas. Each with image, title, short desc, CTA.",
      "effects": "Cards grid, staggered fade-in. Hover: scale 1.03, overlay with CTA button appears, image zoom 1.05."
    },
    {
      "id": "podcasts",
      "component": "Podcasts.tsx",
      "content": "Section title: Podcasts. 3 cards: Elemental (1M+ downloads, 347+ eps), Pop Business, Café con Santiago. Each with cover art description, title, stats, listen links.",
      "effects": "Cards fade-in-up. Hover: lift shadow, play icon animation. Platform links (Spotify, YouTube, Apple) hover color."
    },
    {
      "id": "newsletter",
      "component": "Newsletter.tsx",
      "content": "CTA section: El Newsletter de Santiago. 3000+ suscriptores. Email input + subscribe button. Substack link.",
      "effects": "Background accent gradient. Input focus glow. Button hover scale."
    },
    {
      "id": "contact",
      "component": "Contacto.tsx",
      "content": "Heading: Hablemos. Email: hola@santiagoallamand.com. Social media grid: Instagram, TikTok, Twitter/X, YouTube, LinkedIn, Spotify. Contact form optional.",
      "effects": "Social icons hover: scale + color shift to brand color. Email hover underline. Fade-in-up."
    },
    {
      "id": "footer",
      "component": "Footer.tsx",
      "content": "Santiago Allamand © 2026. Quick links. Social icons row. Legal links.",
      "effects": "Subtle top border gradient. Links hover color."
    }
  ],
  "islands": [
    {
      "name": "ScrollAnimator.tsx",
      "purpose": "Scroll-triggered animations (V7 pattern), smooth scroll, navbar scroll shadow, parallax-lite, counter animation",
      "config": "data-animate attributes: fade-in-up, fade-in-left, fade-in-right, scale-in. Counter animation for stats. Staggered delays via data-delay."
    },
    {
      "name": "MobileMenu.tsx",
      "purpose": "Hamburger menu for mobile nav with slide-in animation"
    },
    {
      "name": "DarkModeToggle.tsx",
      "purpose": "Dark/light mode toggle with localStorage persistence. Swaps CSS variables."
    },
    {
      "name": "CounterStats.tsx",
      "purpose": "Animated number counter (700K, 1.5M, 10+) that counts up when section enters viewport"
    }
  ],
  "seo": {
    "title": "Santiago Allamand | Finanzas Personales, Productividad y Estilo de Vida",
    "description": "Abogado, inversionista, profesor universitario y creador de contenido. Cursos de finanzas personales, productividad y estilo de vida. 700K+ seguidores. Podcasts: Elemental, Pop Business, Café con Santiago.",
    "keywords": "Santiago Allamand, finanzas personales chile, productividad, cursos finanzas, inversiones, ETFs, Elemental Podcast, educación financiera, estilo de vida, presupuesto personal",
    "og_image": "1200x630 with photo + name + tagline",
    "schemas": ["Person", "WebSite", "BreadcrumbList", "Course (for each course)", "PodcastSeries"]
  },
  "images": {
    "strategy": "Use placeholder images initially. User will provide real photos of Santiago Allamand. For courses, use gradient/abstract card designs generated with CSS.",
    "hero_photo": "Professional portrait - user must provide",
    "course_thumbnails": "CSS gradient cards with course titles overlaid",
    "podcast_covers": "CSS gradient cards with podcast names"
  },
  "animations_css": {
    "keyframes": [
      "fade-in-up (translateY 30px to 0, opacity 0 to 1, 0.7s ease-out)",
      "fade-in-left (translateX -30px to 0, opacity 0 to 1, 0.7s ease-out)",
      "fade-in-right (translateX 30px to 0, opacity 0 to 1, 0.7s ease-out)",
      "scale-in (scale 0.95 to 1, opacity 0 to 1, 0.5s ease-out)",
      "slide-in-right (translateX 100% to 0, 0.3s ease-out for mobile menu)",
      "count-up (JS-driven, not CSS)"
    ],
    "hover_effects": [
      "Cards: translateY(-4px) + shadow-lg, 300ms transition",
      "Buttons: scale(1.02) + darken bg, 200ms transition",
      "Links: underline-offset animation or color shift",
      "Social icons: scale(1.1) + brand color, 200ms",
      "Course cards: image zoom scale(1.05) + overlay fade-in"
    ],
    "v7_pattern": true,
    "fallback_timer": 1500,
    "reduced_motion": true
  },
  "dark_mode": {
    "strategy": "CSS class toggle on <html>. data-theme attribute. Tailwind dark: variant. LocalStorage persistence.",
    "light_bg": "#ffffff",
    "dark_bg": "#1a1a2e",
    "light_accent": "#5e67e6",
    "dark_accent": "#d0ff71"
  },
  "lighthouse_targets": {
    "performance": 90,
    "accessibility": 95,
    "best_practices": 95,
    "seo": 100
  }
}
